package com.autojobapply.matching;
import com.autojobapply.config.Config; import com.autojobapply.model.*; import java.util.*;
/** Deterministic, explainable scoring; terms and weights are deliberately visible. */
public final class JobMatcher {
 private static final List<String> SKILLS=List.of("java","spring","spring boot","microservices","kafka","distributed systems","aws","rest","sql","oracle","architecture","system design","event-driven","cloud","leadership");
 private static final Map<String,List<String>> SPECIALIZED_PLATFORMS=Map.of(
         "salesforce",List.of("salesforce","administrator","apex","visualforce","lightning","soql","sosl","sales cloud","service cloud","process builder","data loader"),
         "sap",List.of("sap","s/4hana","abap","sap basis","successfactors","sap fico","sap mm","sap sd"),
         "servicenow",List.of("servicenow","service now","servicenow administrator","servicenow developer","servicenow cmdb","servicenow itsm"),
         "workday",List.of("workday","workday hcm","workday financial","workday studio","workday integration"),
         "oracle fusion",List.of("oracle fusion","oracle hcm","oracle erp cloud","oracle cloud recruiting"),
         "dynamics 365",List.of("dynamics 365","microsoft dynamics","power platform","power apps","power automate")
 ); private final Resume resume; private final ApplicantProfile profile; private final Config config;
 public JobMatcher(Resume r,ApplicantProfile p,Config c){resume=r;profile=p;config=c;}
 public ScoredJob score(Job j){String d=(j.title()+" "+j.description()).toLowerCase();List<String> asked=SKILLS.stream().filter(s->d.contains(s)).toList();List<String> hit=asked.stream().filter(s->resume.text().toLowerCase().contains(s)).toList();List<String> missing=asked.stream().filter(s->!hit.contains(s)).toList();double technical=asked.isEmpty()?0.5:(double)hit.size()/asked.size();double experience=containsBoth(d,"experience","year")&&resume.text().toLowerCase().contains("experience")?1:0.55; double architecture=containsAny(d,"architect","system design","distributed")&&containsAny(resume.text().toLowerCase(),"architect","system design","distributed")?1:0.45;double seniority=containsAny(resume.text().toLowerCase(),"principal","staff","lead","architect")?1:0.55;double domain=technical;int score=(int)Math.round(100*(technical*.35+experience*.25+architecture*.20+seniority*.10+domain*.10)); List<String> rejected=new ArrayList<>();if(!targetSeniority(j.title()))rejected.add("title/seniority not targeted");if(!targetLocation(j.location()))rejected.add("location is not Bay Area or eligible remote");if(score<config.minimumScore())rejected.add("resume-match score "+score+" below threshold "+config.minimumScore());if(!eligibility(j))rejected.add("mandatory profile eligibility is unanswered");specializationMismatch(d).ifPresent(rejected::add);String reason="skills "+hit.size()+"/"+asked.size()+", deterministic weighted score"+(rejected.isEmpty()?"": "; "+String.join("; ",rejected));return new ScoredJob(j,score,hit,missing,rejected.isEmpty(),reason,List.copyOf(rejected));}
 private Optional<String> specializationMismatch(String description){for(var entry:SPECIALIZED_PLATFORMS.entrySet())if(substantivePlatformRequirement(description,entry.getValue())&&!verifiedPlatformEvidence(entry.getKey()))return Optional.of("incompatible specialized platform requirements: "+entry.getKey()+" not evidenced by resume/profile");return Optional.empty();}
 private boolean substantivePlatformRequirement(String description,List<String> signals){long mentions=signals.stream().filter(description::contains).count();return description.contains(signals.getFirst())&&mentions>=3;}
 private boolean verifiedPlatformEvidence(String platform){String evidence=resume.text().toLowerCase();return evidence.contains(platform)||"yes".equalsIgnoreCase(profile.get("skill."+platform+".verified"));}
 private boolean targetSeniority(String title){String t=title.toLowerCase();return t.matches(".*\\b(principal|staff|lead|architect|distinguished|fellow)\\b.*")||t.contains("chief architect");}private boolean targetLocation(String location){String l=location.toLowerCase();return config.includeRemote()&&l.contains("remote")||l.matches(".*\\b(san francisco|san jose|bay area|california|ca|palo alto|sunnyvale|mountain view|santa clara|redwood city|oakland|berkeley)\\b.*" );}private boolean eligibility(Job j){String d=j.description().toLowerCase();if(d.contains("must be authorized")&&profile.get("work.authorization").isBlank())return false;return true;}private boolean containsBoth(String s,String a,String b){return s.contains(a)&&s.contains(b);}private boolean containsAny(String s,String...xs){return Arrays.stream(xs).anyMatch(s::contains);}
}
